import CommsClient
import SwiftUI

/// The networks' brand marks for the avatar badges: vector paths transcribed from
/// Simple Icons v13.21.0 (https://github.com/simple-icons/simple-icons, CC0 1.0), brand
/// colours from the same release (tokens.json `brand`). The marks are trademarks of their
/// owners, used only to say which network a conversation is on. See
/// CommsKit/Sources/CommsUI/List/NetworkMarks-LICENSE.md.
enum NetworkMark {
    /// A white glyph on the brand circle, at `scale` of the badge diameter.
    case glyph(Path, scale: CGFloat)
    /// A mark that already is a circle with the glyph cut out (Telegram): drawn in the brand
    /// colour over a white disc, so the glyph shows white.
    case knockout(Path)
    /// A full-colour mark on a white disc (Slack: its four-colour hash is the brand; a
    /// one-colour hash reads as a generic "#"). Layers are drawn in order, at `scale`.
    case multicolor([(Path, Color)], scale: CGFloat)
    /// No brand mark (generic email): an SF Symbol in white.
    case symbol(String)

    static func mark(for network: CommsNetwork) -> NetworkMark {
        switch network {
        case .imessage, .sms: .glyph(Paths.messagesBubble, scale: 0.92)
        case .whatsapp: .glyph(Paths.whatsapp, scale: 0.6)
        case .telegram: .knockout(Paths.telegram)
        case .messenger: .glyph(Paths.messenger, scale: 0.6)
        case .x: .glyph(Paths.x, scale: 0.5)
        case .discord: .glyph(Paths.discord, scale: 0.62)
        case .matrix: .glyph(Paths.matrix, scale: 0.6)
        case .email: .symbol("envelope.fill")
        case .signal: .glyph(Paths.signal, scale: 0.64)
        case .slack: .multicolor(Paths.slack.map { ($0.path, $0.color.color) }, scale: 0.6)
        case .instagram: .glyph(Paths.instagram, scale: 0.56)
        case .linkedin: .glyph(Paths.linkedin, scale: 0.5)
        case .unknown: .symbol("bubble.left.fill")
        }
    }

    static func color(for network: CommsNetwork) -> Color {
        let b = Tokens.brand
        return switch network {
        case .imessage: b.imessage.color
        case .sms: b.sms.color
        case .whatsapp: b.whatsapp.color
        case .telegram: b.telegram.color
        case .messenger: b.messenger.color
        case .x: b.x.color
        case .discord: b.discord.color
        case .email: b.email.color
        case .matrix: b.matrix.color
        case .signal: b.signal.color
        case .slack: b.slack.color
        case .instagram: b.instagram.color
        case .linkedin: b.linkedin.color
        case .unknown: b.sms.color
        }
    }

